ame":"idx_QuestLine_ID","sql":"CREATE INDEX \"idx_QuestLine_ID\" ON \"QuestLine\" (\"ID\")"},{"name":"idx_QuestMoneyReward_ID","sql":"CREATE INDEX \"idx_QuestMoneyReward_ID\" ON \"QuestMoneyReward\" (\"ID\")"},{"name":"idx_QuestPOIBlob_ID","sql":"CREATE INDEX \"idx_QuestPOIBlob_ID\" ON \"QuestPOIBlob\" (\"ID\")"},{"name":"idx_QuestPOIPoint_ID","sql":"CREATE INDEX \"idx_QuestPOIPoint_ID\" ON \"QuestPOIPoint\" (\"ID\")"},{"name":"idx_QuestSort_ID","sql":"CREATE INDEX \"idx_QuestSort_ID\" ON \"QuestSort\" (\"ID\")"},{"name":"idx_QuestV2_ID","sql":"CREATE INDEX \"idx_QuestV2_ID\" ON \"QuestV2\" (\"ID\")"},{"name":"idx_QuestXP_ID","sql":"CREATE INDEX \"idx_QuestXP_ID\" ON \"QuestXP\" (\"ID\")"},{"name":"idx_SkillLineAbility_ID","sql":"CREATE INDEX \"idx_SkillLineAbility_ID\" ON \"SkillLineAbility\" (\"ID\")"},{"name":"idx_SkillLineAbility_SkillLine","sql":"CREATE INDEX \"idx_SkillLineAbility_SkillLine\" ON \"SkillLineAbility\" (\"SkillLine\")"},{"name":"idx_SkillLineAbility_Spell","sql":"CREATE INDEX \"idx_SkillLineAbility_Spell\" ON \"SkillLineAbility\" (\"Spell\")"},{"name":"idx_SkillLine_ID","sql":"CREATE INDEX \"idx_SkillLine_ID\" ON \"SkillLine\" (\"ID\")"},{"name":"idx_SkillRaceClassInfo_ID","sql":"CREATE INDEX \"idx_SkillRaceClassInfo_ID\" ON \"SkillRaceClassInfo\" (\"ID\")"},{"name":"idx_SpellAuraOptions_ID","sql":"CREATE INDEX \"idx_SpellAuraOptions_ID\" ON \"SpellAuraOptions\" (\"ID\")"},{"name":"idx_SpellAuraOptions_SpellID","sql":"CREATE INDEX \"idx_SpellAuraOptions_SpellID\" ON \"SpellAuraOptions\" (\"SpellID\")"},{"name":"idx_SpellCastTimes_ID","sql":"CREATE INDEX \"idx_SpellCastTimes_ID\" ON \"SpellCastTimes\" (\"ID\")"},{"name":"idx_SpellCastingRequirements_ID","sql":"CREATE INDEX \"idx_SpellCastingRequirements_ID\" ON \"SpellCastingRequirements\" (\"ID\")"},{"name":"idx_SpellCastingRequirements_SpellID","sql":"CREATE INDEX \"idx_SpellCastingRequirements_SpellID\" ON \"SpellCastingRequirements\" (\"SpellID\")"},{"name":"idx_SpellCategory_ID","sql":"CREATE